package com.fream.back.domain.m11.entity;

import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.global.entity.Xwb79Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Table(
        indexes = {
                @Index(name = "idx_user_id", columnList = "user_id"),
                @Index(name = "idx_is_default", columnList = "is_default")
        }
)
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xms98 extends Xwb79Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xrd81 user;

    @Column(nullable = false)
    private String recipientName;

    @Column(nullable = false)
    private String phoneNumber;

    @Column(nullable = false)
    private String zipCode;

    @Column(nullable = false)
    private String address;

    private String detailedAddress;

    @Column(name = "is_default")
    private boolean isDefault;


    public void updateAddress(String recipientName, String phoneNumber, String zipCode,
                              String address, String detailedAddress, Boolean isDefault) {
        if (recipientName != null) {
            this.recipientName = recipientName;
        }
        if (phoneNumber != null) {
            this.phoneNumber = phoneNumber;
        }
        if (zipCode != null) {
            this.zipCode = zipCode;
        }
        if (address != null) {
            this.address = address;
        }
        if (detailedAddress != null) {
            this.detailedAddress = detailedAddress;
        }
        if (isDefault != null) {
            this.isDefault = isDefault;
        }
    }


    public void assignUser(Xrd81 user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }
